# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SİNİR SİSTEMİ PARÇALARI ARASINDAKİ İŞLEVSEL KOORDİNASYON AĞI</text>\n  <rect x="20" y="55" width="145" height="175" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="92" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Duyusal Giriş</text>\n  <text x="30" y="102" font-size="10.5" fill="#334155">• Reseptör uyarıyı alır.</text>\n  <text x="30" y="122" font-size="10.5" fill="#334155">• ÇSS Duyu Nöronu</text>\n  <text x="38" y="138" font-size="10.5" fill="#475569">impulsu omurilik arka</text>\n  <text x="38" y="154" font-size="10.5" fill="#475569">kökünden MSS\'ye taşır.</text>\n  <text x="30" y="178" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Talamus (koku hariç)</text>\n  <text x="38" y="194" font-size="10.5" fill="#475569">duyuları sınıflandırır.</text>\n\n  <rect x="190" y="55" width="155" height="175" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="267" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">2. Kortikal Değerlendirme</text>\n  <text x="200" y="102" font-size="10.5" fill="#334155">• Uç Beyin (Korteks)</text>\n  <text x="208" y="118" font-size="10.5" fill="#475569">bilinçli algı ve istemli</text>\n  <text x="208" y="134" font-size="10.5" fill="#475569">motor kararı üretir.</text>\n  <text x="200" y="158" font-size="10.5" font-weight="bold" fill="#6d28d9">• Beyincik + Orta Beyin</text>\n  <text x="208" y="174" font-size="10.5" fill="#475569">kas tonusunu, dengeyi ve</text>\n  <text x="208" y="190" font-size="10.5" fill="#475569">eş güdümü düzenler.</text>\n\n  <rect x="370" y="55" width="145" height="175" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="442" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Otonom Denetim</text>\n  <text x="380" y="102" font-size="10.5" fill="#334155">• Hipotalamus iç dengeyi</text>\n  <text x="388" y="118" font-size="10.5" fill="#475569">(ısı, su, hormon) izler.</text>\n  <text x="380" y="142" font-size="10.5" fill="#334155">• Omurilik Soğanı ve Pons</text>\n  <text x="388" y="158" font-size="10.5" fill="#475569">solunum, dolaşım ve</text>\n  <text x="388" y="174" font-size="10.5" fill="#475569">hayati refleksleri yönetir.</text>\n\n  <rect x="540" y="55" width="140" height="175" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="610" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">4. Motor Yanıt (Tepki)</text>\n  <text x="550" y="102" font-size="10.5" fill="#334155">• Omurilik ön kökünden</text>\n  <text x="558" y="118" font-size="10.5" fill="#475569">çıkan motor nöronlar:</text>\n  <text x="550" y="142" font-size="10.5" font-weight="bold" fill="#15803d">• Somatik sinirlerle</text>\n  <text x="558" y="158" font-size="10.5" fill="#475569">çizgili kasları uyarır.</text>\n  <text x="550" y="182" font-size="10.5" font-weight="bold" fill="#15803d">• Otonom sinirlerle</text>\n  <text x="558" y="198" font-size="10.5" fill="#475569">iç organları düzenler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BAŞLICA SİNİR SİSTEMİ RAHATSIZLIKLARI VE PATOFİZYOLOJİK MEKANİZMALARI</text>\n  <rect x="20" y="48" width="155" height="192" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="97" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">Multipl Skleroz (MS)</text>\n  <text x="30" y="94" font-size="10" fill="#334155">• Otoimmün hastalık</text>\n  <text x="30" y="114" font-size="10" font-weight="bold" fill="#991b1b">• Hedef: MSS\'deki</text>\n  <text x="38" y="128" font-size="10" font-weight="bold" fill="#991b1b">miyelin kılıflar</text>\n  <text x="30" y="150" font-size="10" fill="#334155">• Plak oluşumu nedeniyle</text>\n  <text x="38" y="164" font-size="10" fill="#475569">impuls iletimi aksar.</text>\n  <text x="30" y="186" font-size="10" fill="#334155">• Belirti: Kas güçsüzlüğü,</text>\n  <text x="38" y="200" font-size="10" fill="#475569">uyuşma, denge kaybı.</text>\n\n  <rect x="190" y="48" width="155" height="192" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="267" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Alzheimer</text>\n  <text x="200" y="94" font-size="10" fill="#334155">• Nörodejeneratif yıkım</text>\n  <text x="200" y="114" font-size="10" font-weight="bold" fill="#1e40af">• Hedef: Uç beyin kabuğu</text>\n  <text x="208" y="128" font-size="10" font-weight="bold" fill="#1e40af">ve hipokampus</text>\n  <text x="200" y="150" font-size="10" fill="#334155">• Amiloid plak birikimi ve</text>\n  <text x="208" y="164" font-size="10" fill="#475569">asetilkolin azalması</text>\n  <text x="200" y="186" font-size="10" fill="#334155">• Belirti: Yakın hafıza</text>\n  <text x="208" y="200" font-size="10" fill="#475569">kaybı, bilişsel gerileme.</text>\n\n  <rect x="360" y="48" width="155" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="437" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Parkinson</text>\n  <text x="370" y="94" font-size="10" fill="#334155">• Motor kontrol bozukluğu</text>\n  <text x="370" y="114" font-size="10" font-weight="bold" fill="#b45309">• Hedef: Orta beyindeki</text>\n  <text x="378" y="128" font-size="10" font-weight="bold" fill="#b45309">dopamin nöronları</text>\n  <text x="370" y="150" font-size="10" fill="#334155">• Dopamin eksikliğiyle</text>\n  <text x="378" y="164" font-size="10" fill="#475569">kas tonusu bozulur.</text>\n  <text x="370" y="186" font-size="10" fill="#334155">• Belirti: İstemsiz titreme,</text>\n  <text x="378" y="200" font-size="10" fill="#475569">yavaş ve küçük adımlar.</text>\n\n  <rect x="530" y="48" width="150" height="192" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="605" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Epilepsi ve Felç</text>\n  <text x="540" y="94" font-size="10" font-weight="bold" fill="#166534">• Epilepsi (Sara):</text>\n  <text x="548" y="108" font-size="10" fill="#334155">Nöronların ani ve aşırı</text>\n  <text x="548" y="122" font-size="10" fill="#334155">elektriksel deşarjı.</text>\n  <text x="540" y="148" font-size="10" font-weight="bold" fill="#166534">• Felç (İnme) / Kuduz:</text>\n  <text x="548" y="162" font-size="10" fill="#334155">Beyin damar tıkanıklığı,</text>\n  <text x="548" y="176" font-size="10" fill="#334155">omurilik zedelenmesi ve</text>\n  <text x="548" y="190" font-size="10" fill="#334155">viral nöron tahribatı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SİNİR SİSTEMİ SAĞLIĞINI KORUMA VE NÖROPLASTİSİTE İLKELERİ</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Destekleyici ve Koruyucu Faktörler</text>\n  <text x="40" y="102" font-size="11" fill="#14532d">• B1, B6, B12 vitaminleri ve Omega-3 yağ asitleri</text>\n  <text x="48" y="118" font-size="10.5" fill="#166534">(Miyelin kılıf ve nörotransmitter sentezi)</text>\n  <text x="40" y="142" font-size="11" fill="#14532d">• Düzenli Gece Uykusu (BOS ile toksin temizliği</text>\n  <text x="48" y="158" font-size="10.5" fill="#166534">ve uzun süreli hafıza konsolidasyonu)</text>\n  <text x="40" y="182" font-size="11" fill="#14532d">• Fiziksel egzersiz ve zihinsel aktiviteler</text>\n  <text x="48" y="198" font-size="10.5" fill="#166534">(Yeni sinaps oluşumu / Nöroplastisite)</text>\n  <text x="40" y="222" font-size="11" font-weight="bold" fill="#15803d">• Kask ve emniyet kemeri (Travma koruması)</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Sinir Sistemine Zarar Veren Etkenler</text>\n  <text x="380" y="102" font-size="11" fill="#7f1d1d">• Alkol, sigara ve bağımlılık yapıcı maddeler</text>\n  <text x="388" y="118" font-size="10.5" fill="#991b1b">(Sinaptik iletimi bozar, beyincik ve korteksi yıpratır)</text>\n  <text x="380" y="142" font-size="11" fill="#7f1d1d">• Kronik stres ve aşırı kortizol hormonu</text>\n  <text x="388" y="158" font-size="10.5" fill="#991b1b">(Hipokampus nöronlarında körelme ve unutkanlık)</text>\n  <text x="380" y="182" font-size="11" fill="#7f1d1d">• Ağır metaller (Kurşun, cıva) ve radyasyon</text>\n  <text x="380" y="206" font-size="11" fill="#7f1d1d">• Doktor kontrolü dışında bilinçsiz ilaç</text>\n  <text x="388" y="222" font-size="10.5" fill="#991b1b">ve uyarıcı madde kullanımı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
